<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import SrmModal from '../srm-ui/SrmModal.vue'
const props=defineProps({api:Function,context:Object,categories:Array,supplierId:{type:String,default:''}})
const rows=ref([]),templates=ref([]),suppliers=ref([]),summary=ref(null),selected=ref(null),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),page=ref(1),total=ref(0),month=ref(''),category=ref(''),grade=ref(''),sid=ref(props.supplierId),end=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()).replace('/','-'))
// Use a fixed YYYY-MM, independent of browser locale's field order.
const nowParts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).formatToParts(new Date());const currentMonth=nowParts.find(x=>x.type==='year').value+'-'+nowParts.find(x=>x.type==='month').value;end.value=currentMonth
const labels=['交付','质量','成本','服务'],gradeLabels={STRATEGIC:'战略',PREFERRED:'优选',QUALIFIED:'合格',WATCH:'观察',ELIMINATION_SUGGESTED:'淘汰建议（须审批）'}
const sourceLabels={HISTORICAL:'历史导入',SANDBOX:'沙箱数据',APPEAL_CORRECTION:'申诉修正'}
const canWrite=computed(()=>!props.context.portal&&props.context.roles.some(r=>['SQE','CAT-MGR','superAdmin'].includes(r)))
const canReview=computed(()=>!props.context.portal&&props.context.roles.some(r=>['SQE','superAdmin'].includes(r)))
const allowed=computed(()=>!props.context.portal||props.context.roles.some(r=>['ADMIN','QUOTE','QUALITY','FINANCE'].includes(r)))
const form=reactive({period:currentMonth,sourceType:'HISTORICAL',sourceRef:'',scores:[80,80,80,80],effectivePeriod:currentMonth,weights:[30,35,20,15],thresholds:[90,80,70,60],reason:'',comment:'',approve:true})
const trendMonths=ref(12)
const csvRows=ref([]),csvName=ref(''),reviewId=ref('');let importKey='',importSignature=''
const latest=computed(()=>selected.value?.history?.[0]?.snapshot)
const chartPoints=computed(()=>(summary.value?.trend||[]).map(r=>({period:r.period,total:Number(r.total)})))
const points=computed(()=>chartPoints.value.map((r,i)=>`${30+i*540/Math.max(1,chartPoints.value.length-1)},${150-r.total*1.2}`).join(' '))
const p=(path,body,method='GET',raw=false)=>props.api('/performance'+path,body,method,raw)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const data=await p('/scores?'+new URLSearchParams({current:page.value,size:20,period:month.value,category:category.value,grade:grade.value}));rows.value=data.records;total.value=data.total}
async function loadSummary(){if(sid.value)summary.value=await p('/suppliers/'+sid.value+'/summary?'+new URLSearchParams({endPeriod:end.value,months:trendMonths.value}));else summary.value=null}
async function init(){if(!allowed.value)return;templates.value=await p('/templates');const data=await props.api('/suppliers?size=100');suppliers.value=data.records;if(!sid.value)sid.value=props.context.supplierId||suppliers.value[0]?.id||'';await load();await loadSummary()}
async function inspect(row){selected.value=await p('/scores/'+row.id);modal.value='detail'}
function open(kind){error.value='';notice.value='';modal.value=kind;csvRows.value=[];csvName.value='';if(kind==='template'){Object.assign(form,{effectivePeriod:currentMonth,weights:[...templates.value[0].config.weights],thresholds:[...templates.value[0].config.thresholds]})}if(kind==='appeal')form.reason='';if(kind==='input'){form.period=currentMonth;form.sourceRef='';form.scores=[80,80,80,80]}}
async function saveTemplate(){await p('/templates',{expectedVersion:templates.value[0].version,effectivePeriod:form.effectivePeriod,weights:form.weights.map(Number),thresholds:form.thresholds.map(Number)},'POST');templates.value=await p('/templates');modal.value='';notice.value='统一模板新版本已发布，历史快照保留'}
async function importScores(){const data=csvRows.value.length?csvRows.value:[{supplierId:sid.value,period:form.period,sourceType:form.sourceType,sourceRef:form.sourceRef,scores:form.scores.map(Number)}];if(!data[0].supplierId)throw new Error('请先选择供应商');const signature=JSON.stringify(data);if(signature!==importSignature){importSignature=signature;importKey='perf-'+crypto.randomUUID()}await p('/imports',{requestKey:importKey,rows:data},'POST');let done=0;for(const r of data){await p('/calculate',{supplierId:r.supplierId,period:r.period},'POST');done++}modal.value='';notice.value=`已保存来源并计算 ${done} 份月度评分`;await load();await loadSummary()}
async function calculate(){if(!sid.value)throw new Error('请先选择供应商');await p('/calculate',{supplierId:sid.value,period:end.value},'POST');notice.value='本月评分已重算，相同输入不增加版本';await load();await loadSummary()}
async function submitAppeal(){await p('/scores/'+selected.value.id+'/appeals',{scoreVersion:selected.value.rowVersion,reason:form.reason},'POST');selected.value=await p('/scores/'+selected.value.id);modal.value='detail';notice.value='申诉已提交SQE复核';await load()}
function startReview(appeal){reviewId.value=appeal.id;form.comment='';form.approve=true;form.scores=[...latest.value.scores];modal.value='review'}
async function review(){selected.value=await p('/appeals/'+reviewId.value+'/review',{scoreVersion:selected.value.rowVersion,approve:form.approve,comment:form.comment,...(form.approve?{correctedScores:form.scores.map(Number)}:{})},'POST');modal.value='detail';notice.value='复核完成，结果和修正版本已留痕';await load();await loadSummary()}
async function download(){const blob=await p('/export?'+new URLSearchParams({period:month.value,category:category.value,grade:grade.value}),undefined,'GET',true);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='绩效分级.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parseCSV(text){const records=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(!quoted&&(c===','||c==='\n')){row.push(value.replace(/\r$/,''));value='';if(c==='\n'){if(row.some(x=>x.trim()))records.push(row);row=[]}}else value+=c}if(quoted)throw new Error('CSV引号未闭合');row.push(value.replace(/\r$/,''));if(row.some(x=>x.trim()))records.push(row);return records}
async function readCSV(event){error.value='';try{const f=event.target.files[0];if(!f)return;if(f.size>1024*1024)throw new Error('CSV文件不能超过1MB');const data=parseCSV((await f.text()).replace(/^\uFEFF/,''));const header=data.shift();if(header?.join(',')!=='supplierId,period,sourceType,sourceRef,delivery,quality,cost,service')throw new Error('CSV表头与示例不一致');if(!data.length||data.length>500)throw new Error('每批请提供1~500行');csvRows.value=data.map((r,i)=>{if(r.length!==8||r.slice(4).some(x=>!x.trim()||!Number.isFinite(Number(x))))throw new Error(`第${i+2}行列数或分值错误`);return {supplierId:r[0],period:r[1],sourceType:r[2],sourceRef:r[3],scores:r.slice(4).map(Number)}});csvName.value=f.name}catch(e){csvRows.value=[];error.value=e.message}}
function csvExample(){const text='\uFEFFsupplierId,period,sourceType,sourceRef,delivery,quality,cost,service\n'+(sid.value||'供应商ID')+','+currentMonth+',HISTORICAL,历史台账编号,80,85,90,95\n';const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='绩效历史导入示例.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>run(init));watch(()=>props.supplierId,value=>{sid.value=value;run(loadSummary)})
</script>
<template>
<section class="performance-panel">
 <div v-if="!allowed" class="empty-state">当前联系人角色无绩效查看权限，请联系供应商管理员。</div>
 <template v-else>
 <div class="panel-heading"><div><h2>供应商绩效</h2><p>月度评分、来源追溯与申诉复核</p></div><div class="perf-actions"><button class="btn" :disabled="busy" @click="run(load)">刷新评分</button><button class="btn" :disabled="busy" @click="run(download)">导出绩效 Excel</button><button v-if="canWrite" class="btn" @click="open('template')">统一评分模板</button><button v-if="canWrite" class="btn primary" @click="open('input')">录入或导入评分</button></div></div>
 <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="info-note" role="status">{{notice}}</p>
 <form class="table-toolbar" @submit.prevent="page=1;run(load)"><input type="month" aria-label="绩效月份筛选" v-model="month" :max="currentMonth" /><select aria-label="绩效品类筛选" v-model="category"><option value="">全部品类</option><option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</option></select><select aria-label="绩效等级筛选" v-model="grade"><option value="">全部绩效等级</option><option v-for="(name,key) in gradeLabels" :key="key" :value="key">{{name}}</option></select><button class="btn" :disabled="busy">查询绩效</button></form>
 <div class="table-scroll"><table><thead><tr><th>供应商 / 月份</th><th>交付</th><th>质量</th><th>成本</th><th>服务</th><th>总分</th><th>绩效等级</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.supplierName}}<small class="perf-small">{{r.period}} · 版本 {{r.rowVersion}}</small></td><td>{{r.deliverScore}}</td><td>{{r.qualityScore}}</td><td>{{r.costScore}}</td><td>{{r.serviceScore}}</td><td><strong>{{r.total}}</strong></td><td>{{gradeLabels[r.grade]}}<small v-if="r.pendingAppeals" class="perf-small">待SQE复核</small></td><td><button class="text-btn" @click="run(()=>inspect(r))">评分明细</button></td></tr></tbody></table><div v-if="!rows.length" class="empty-state">当前范围暂无月度评分，请先录入有来源的历史数据。</div></div>
 <div class="table-footer"><span>共 {{total}} 份月度评分</span><div><button :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}}</span><button :disabled="busy||page*20>=total" @click="page++;run(load)">下一页</button></div></div>
 <div class="perf-summary"><h3>近{{trendMonths}}个月趋势与定点参考</h3><form class="table-toolbar" @submit.prevent="run(loadSummary)"><select aria-label="绩效供应商" v-model="sid" :disabled="!!supplierId"><option value="">请选择供应商</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select><input aria-label="绩效截止月份" type="month" v-model="end" :max="currentMonth" required /><select aria-label="绩效趋势月数" v-model.number="trendMonths"><option v-for="n in [3,6,12,24,36]" :key="n" :value="n">近{{n}}个月</option></select><button class="btn" :disabled="busy">查看趋势</button><button v-if="canWrite" type="button" class="btn" :disabled="busy||!sid" @click="run(calculate)">重算所选月份</button></form>
 <template v-if="summary"><p v-if="summary.requiresApprovedException" class="info-note">无绩效历史：不生成默认分数，后续定点须走获批例外规则。</p><p v-else>有效 {{summary.validMonths}} / {{summary.requestedMonths}} 个月 · 总分均值 <strong>{{summary.averageTotal}}</strong><span v-if="summary.insufficientHistory"> · 历史不足{{summary.requestedMonths}}个月，按实际有效月份计算</span></p><p v-if="summary.missingPeriods.length" class="muted">缺失月份：{{summary.missingPeriods.join('、')}}</p>
 <svg v-if="chartPoints.length" viewBox="0 0 600 190" role="img" :aria-label="'近'+summary.requestedMonths+'月绩效趋势'" class="perf-chart"><line x1="30" y1="150" x2="570" y2="150" stroke="#aabdb4"/><polyline :points="points" fill="none" stroke="#167c68" stroke-width="3"/><g v-for="(r,i) in chartPoints" :key="r.period"><circle :cx="30+i*540/Math.max(1,chartPoints.length-1)" :cy="150-r.total*1.2" r="4" fill="#167c68"/><text :x="30+i*540/Math.max(1,chartPoints.length-1)" :y="140-r.total*1.2" text-anchor="middle">{{r.total}}</text><text :x="30+i*540/Math.max(1,chartPoints.length-1)" y="175" text-anchor="middle">{{r.period}}</text></g></svg></template></div>
 <div class="info-note">评分使用可追溯的历史或沙箱数据。绩效等级可更新合格供应商等级；淘汰建议须另走审批，不直接改变准入状态。</div>
 </template>
 <SrmModal v-if="modal==='template'" title="全司统一评分模板" @close="modal=''"><form @submit.prevent="run(saveTemplate)"><p>当前版本 {{templates[0]?.version}}，适用于所有品类。发布新版本保留历史评分快照。</p><label>生效月份<input aria-label="模板生效月份" type="month" v-model="form.effectivePeriod" required /></label><div class="perf-grid"><label v-for="(name,i) in labels" :key="name">{{name}}权重（%）<input :aria-label="name+'权重'" type="number" min="0" max="100" step="0.01" v-model.number="form.weights[i]" required /></label></div><p>权重合计：{{form.weights.reduce((a,b)=>a+Number(b),0)}}%</p><div class="perf-grid"><label v-for="(name,i) in ['战略','优选','合格','观察']" :key="name">{{name}}下限<input :aria-label="name+'下限'" type="number" min="0" max="100" step="0.01" v-model.number="form.thresholds[i]" required /></label></div><p class="muted">低于观察下限：淘汰建议。阈值须严格递减。</p><p v-if="error" class="form-error">{{error}}</p><button class="btn primary" :disabled="busy">发布模板新版本</button></form></SrmModal>
 <SrmModal v-if="modal==='input'" title="录入或导入历史评分" @close="modal=''"><form @submit.prevent="run(importScores)"><label>供应商<select aria-label="导入绩效供应商" v-model="sid" :required="!csvRows.length"><option value="">请选择</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><template v-if="!csvRows.length"><label>评分月份<input type="month" aria-label="录入评分月份" v-model="form.period" :max="currentMonth" required /></label><label>数据来源<select aria-label="绩效数据来源" v-model="form.sourceType"><option value="HISTORICAL">历史台账</option><option value="SANDBOX">沙箱数据</option></select></label><label>来源凭据编号<input aria-label="绩效来源凭据" v-model="form.sourceRef" maxlength="256" required placeholder="原始台账、批次或业务单据编号" /></label><div class="perf-grid"><label v-for="(name,i) in labels" :key="name">{{name}}分<input :aria-label="name+'分'" type="number" v-model.number="form.scores[i]" min="0" max="100" step="0.01" required /></label></div></template><hr/><button type="button" class="btn" @click="csvExample">下载CSV示例</button><label>批量导入CSV（UTF-8，最多500行）<input aria-label="绩效CSV文件" type="file" accept=".csv,text/csv" @change="readCSV" /></label><p v-if="csvRows.length">{{csvName}}：已解析 {{csvRows.length}} 行，将逐月计算；来源保留，不代表外部系统联调。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary" :disabled="busy">{{busy?'正在保存并计算…':'保存来源并计算'}}</button></form></SrmModal>
 <SrmModal v-if="modal==='detail'&&selected" title="月度绩效明细" @close="modal=''"><h3>{{selected.supplierName}} · {{selected.period}}</h3><p>总分 {{selected.total}} · {{gradeLabels[selected.grade]}} · 版本 {{selected.rowVersion}}</p><p v-if="latest">来源：{{sourceLabels[latest.sourceType]}} / {{latest.sourceRef}} · 模板版本 {{latest.templateVersion}}</p><table v-if="latest"><thead><tr><th>指标</th><th>原始分</th><th>权重</th><th>加权贡献</th></tr></thead><tbody><tr v-for="(name,i) in labels" :key="name"><td>{{name}}</td><td>{{latest.scores[i]}}</td><td>{{latest.weights[i]}}%</td><td>{{latest.contributions[i]}}</td></tr></tbody></table><details v-for="h in selected.history" :key="h.revision"><summary>评分版本 {{h.revision}} · 总分 {{h.snapshot.total}}</summary><p>来源：{{sourceLabels[h.snapshot.sourceType]}} / {{h.snapshot.sourceRef}}</p><p>输入版本 {{h.snapshot.inputRevision}} · 模板 {{h.snapshot.templateVersion}} · 分值 {{h.snapshot.scores.join(' / ')}}</p></details><h3>申诉与复核记录</h3><article v-for="a in selected.appeals" :key="a.id"><p>{{a.status==='PENDING'?'待SQE复核':a.status==='APPROVED'?'已批准修正':'已驳回'}}：{{a.reason}}</p><p v-if="a.reviewComment">复核意见：{{a.reviewComment}}</p><button v-if="canReview&&a.status==='PENDING'" class="btn" @click="startReview(a)">复核申诉</button></article><p v-if="!selected.appeals.length" class="muted">暂无申诉记录</p><button v-if="context.portal&&!selected.appeals.some(a=>a.status==='PENDING')" class="btn" @click="open('appeal')">发起绩效申诉</button><p v-if="error" class="form-error">{{error}}</p></SrmModal>
 <SrmModal v-if="modal==='appeal'" title="发起绩效申诉" @close="modal='detail'"><form @submit.prevent="run(submitAppeal)"><label>申诉说明<textarea aria-label="绩效申诉说明" v-model="form.reason" required maxlength="1000" /></label><p v-if="error" class="form-error">{{error}}</p><button class="btn primary" :disabled="busy">提交绩效申诉</button></form></SrmModal>
 <SrmModal v-if="modal==='review'" title="SQE绩效复核" @close="modal='detail'"><form @submit.prevent="run(review)"><label>复核决定<select aria-label="绩效复核决定" v-model="form.approve"><option :value="true">批准并修正</option><option :value="false">驳回，保留原评分</option></select></label><div v-if="form.approve" class="perf-grid"><label v-for="(name,i) in labels" :key="name">修正{{name}}分<input :aria-label="'修正'+name+'分'" type="number" min="0" max="100" step="0.01" v-model.number="form.scores[i]" required /></label></div><label>复核意见<textarea aria-label="绩效复核意见" v-model="form.comment" required maxlength="1000" /></label><p v-if="error" class="form-error">{{error}}</p><button class="btn primary" :disabled="busy">确认绩效复核</button></form></SrmModal>
</section>
</template>
<style scoped>
.performance-panel{min-width:0}.performance-panel .table-footer button{width:auto;min-width:64px;white-space:nowrap}.perf-actions{display:flex;gap:8px;flex-wrap:wrap}.perf-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.perf-small{display:block;color:#71877d;font-size:12px;margin-top:4px}.perf-summary{padding:20px;border-top:1px solid #e1e9e5}.perf-chart{width:100%;max-width:850px;min-height:160px;background:#f7faf8;border-radius:12px}.perf-chart text{font-size:11px;fill:#35584b}details,article{padding:12px 0;border-bottom:1px solid #e1e9e5}textarea{width:100%;min-height:90px;border:1px solid #cbd9d1;border-radius:8px;padding:10px;font:inherit;box-sizing:border-box}.perf-summary .table-toolbar{padding-left:0}label{display:block;margin:12px 0}input,select{max-width:100%}
</style>
